    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values
    (v_aula_id, 1, $p$Warren compara a estratégia evangelística de muitas igrejas a Charlie Brown, que atira a flecha e depois desenha o alvo ao redor dela, sem mirar em ninguém. A sua igreja tem um alvo evangelístico definido, ou os esforços são lançados ao acaso na esperança de atingir alguém?$p$, 'reflexao', null),
