    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values
    (v_aula_id, 1, $p$Warren mostra que no Pentecoste a multidão se converteu porque sentiu a presença de Deus e entendeu a mensagem na própria língua, concluindo que poucos vêm a Cristo por argumentos puramente intelectuais. Em seus cultos, o que tem peso maior: criar condições para que a presença de Deus seja perceptível, ou vencer pela técnica e pela apologética?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$O autor afirma que 'vidas transformadas' são o que de fato atrai os não-cristãos, mais do que púlpito, toga ou produção, e por isso inclui testemunhos semanais. Sua igreja exibe transformação real de vidas de forma visível, ou tem apostado em elementos secundários esperando que tragam os sem-igreja?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$Baseado em 1 Coríntios 14, Warren defende que é prova de maturidade ajustar voluntariamente as práticas de adoração para acolher o não-cristão presente. Os membros mais maduros da sua igreja estão dispostos a 'servir' em vez de 'servir-se', abrindo mão das próprias preferências de culto?$p$, 'reflexao', null);
  end if;

