    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values
    (v_aula_id, 1, $p$Warren explica que a maioria dos membros não traz amigos não-cristãos porque o culto é incompreensível para os de fora, e que concentrar quase todo o tempo nos cristãos e mudar o foco só nos dois minutos finais é autodestrutivo. O seu culto é, do começo ao fim, relevante o bastante para que um membro queira trazer um colega de trabalho?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$O autor insiste que a primeira emoção do visitante é o medo, e que ele decide se volta antes mesmo da pregação, detalhando barreiras práticas — estacionamento, recepção, placas, anonimato. Quais barreiras concretas a sua igreja ainda impõe aos de fora, e o que você removeria se olhasse o templo 'com os olhos de um visitante'?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$Warren afirma que o prédio comunica uma mensagem que pode contradizer o que dizemos — iluminação, limpeza dos banheiros, temperatura — e que nos tornamos cegos a esses defeitos depois de poucas semanas. Que mensagem não intencional o ambiente físico da sua igreja tem transmitido, e quando foi a última vez que você o avaliou de fato?$p$, 'reflexao', null);
  end if;

