    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values
    (v_aula_id, 1, $p$Warren confessa que seu maior erro inicial foi subestimar o poder da música e tentar agradar a todos os gostos num mesmo culto, frustrando a todos, até decidir 'combinar a música com o grupo-alvo'. Sua igreja tomou uma decisão clara sobre quem deseja alcançar e qual estilo musical condiz com isso, ou ainda tenta agradar a todos?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$O autor argumenta que não existe música 'sagrada' — só letras sagradas — e mostra que hinos hoje reverenciados já foram condenados como vulgares em sua época. Quanto da sua resistência (ou da sua igreja) a determinado estilo é convicção bíblica e quanto é apenas tradição confundida com ortodoxia?$p$, 'reflexao', null),
